import{_ as r,K as l,a as o,c as d,ac as e,b as s,q as n}from"./chunks/framework.BSuaGltH.js";const _=JSON.parse('{"title":"足球规则 · 适用范围与版本至六、守门员与换人的特殊规则","description":"十一人制足球的比赛流程、越位、手球、犯规判罚与定位球规则","frontmatter":{"title":"足球规则 · 适用范围与版本至六、守门员与换人的特殊规则","description":"十一人制足球的比赛流程、越位、手球、犯规判罚与定位球规则","splitFrom":"life/personal/sports/football-rules.md","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"基础学习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"足球规则","summary":"十一人制足球的比赛流程、越位、手球、犯规判罚与定位球规则","status":"active","related":[{"title":"第七号嫌疑人","link":"/life/personal/reading-games/suspect-number-seven","kind":"生活记录","scope":"general","audience":"general"},{"title":"佳能入门","link":"/life/personal/photography/canon","kind":"生活记录","scope":"general","audience":"general"},{"title":"《十翼》逐篇阅读：七种十篇怎样帮助理解《周易》","link":"/life/personal/yijing/ten-wings","kind":"基础学习","scope":"general","audience":"general"},{"title":"《算法》书目与主题导读（版本待确认）","link":"/life/personal/books/computing/algorithms","kind":"书籍导读","scope":"general","audience":"general"},{"title":"《周易》是怎样的一部书：经、传、注与成书问题","link":"/life/personal/yijing/text-history","kind":"基础学习","scope":"general","audience":"general"}],"prev":{"text":"足球规则","link":"/life/personal/sports/football-rules"},"next":{"text":"足球规则 · 七、三个完整判罚场景至官方来源与核对范围","link":"/life/personal/sports/football-rules-part-02"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"足球规则","link":"/life/personal/sports/football-rules"},"next":{"text":"足球规则 · 七、三个完整判罚场景至官方来源与核对范围","link":"/life/personal/sports/football-rules-part-02"}},"headers":[],"relativePath":"life/personal/sports/football-rules-part-01.md","filePath":"life/personal/sports/football-rules-part-01.md"}'),i={name:"life/personal/sports/football-rules-part-01.md"};function p(h,t,c,b,u,f){const a=l("ArticleImage");return o(),d("div",null,[t[0]||(t[0]=e('<h1 id="足球规则-·-适用范围与版本至六、守门员与换人的特殊规则" tabindex="-1">足球规则 · 适用范围与版本至六、守门员与换人的特殊规则 <a class="header-anchor" href="#足球规则-·-适用范围与版本至六、守门员与换人的特殊规则" aria-label="Permalink to &quot;足球规则 · 适用范围与版本至六、守门员与换人的特殊规则&quot;">​</a></h1><p><a href="/life/personal/sports/football-rules">返回分篇目录</a></p><p>足球的基本目标是在规定时间内，将球合法地整体送入对方球门。判断争议时，先看球是否还在比赛中，再看具体行为，最后确定如何恢复比赛以及是否出牌。</p><h2 id="足球规则" tabindex="-1">足球规则 <a class="header-anchor" href="#足球规则" aria-label="Permalink to &quot;足球规则 {#足球规则}&quot;">​</a></h2><p>足球的基本目标是在规定时间内，将球合法地整体送入对方球门。判断争议时，先看球是否还在比赛中，再看具体行为，最后确定如何恢复比赛以及是否出牌。</p><h2 id="适用范围与版本" tabindex="-1">适用范围与版本 <a class="header-anchor" href="#适用范围与版本" aria-label="Permalink to &quot;适用范围与版本 {#适用范围与版本}&quot;">​</a></h2><p>本文介绍标准十一人制足球，以 IFAB《Laws of the Game 2026/27》为依据。五人制、七人制、青少年比赛及特殊赛事可能另有规定，换人名额、加时赛和 VAR 使用情况应以比赛规程为准。</p><h2 id="一、人数、场地与基本装备" tabindex="-1">一、人数、场地与基本装备 <a class="header-anchor" href="#一、人数、场地与基本装备" aria-label="Permalink to &quot;一、人数、场地与基本装备 {#一、人数、场地与基本装备}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>标准规则</th></tr></thead><tbody><tr><td>场上人数</td><td>每队最多 11 人，其中 1 人为守门员</td></tr><tr><td>最低人数</td><td>原则上少于 7 人不能开始或继续比赛；规则规定的临时离场情形另有例外</td></tr><tr><td>一般场地</td><td>长 90～120 米、宽 45～90 米，边线必须长于球门线</td></tr><tr><td>国际比赛场地</td><td>长 100～110 米、宽 64～75 米；105 × 68 米是常见规格</td></tr><tr><td>球门</td><td>两柱内侧间距 7.32 米，横梁下沿距地面 2.44 米</td></tr><tr><td>罚球点</td><td>距球门线中点 11 米</td></tr><tr><td>基本装备</td><td>有袖上衣、短裤、球袜、护腿板、鞋；不得佩戴危险物品或首饰</td></tr></tbody></table><p>场地线属于它所界定的区域，因此罚球区线属于罚球区。球压在边线或球门线上仍可能处于比赛中，必须整体越过才算出界或进球。</p><p>正式比赛通常允许最多更换 5 人，具体由赛事决定；实行 5 人换人制的顶级成人赛事通常有 3 次比赛中的换人机会，中场换人不占次数。同一停顿换多人通常算一次机会，加时增加名额等须查规程。被换下者一般不能重新上场，只有获准采用回场换人制的比赛例外。</p><h2 id="看图认识两个容易混叫的区域" tabindex="-1">看图认识两个容易混叫的区域 <a class="header-anchor" href="#看图认识两个容易混叫的区域" aria-label="Permalink to &quot;看图认识两个容易混叫的区域 {#看图认识两个容易混叫的区域}&quot;">​</a></h2>',12)),s("p",null,[n(a,{src:"/images/sports/football-pitch.svg",alt:"足球场比例图：常见105乘68米场地、罚球区、球门区和罚球点"})]),t[1]||(t[1]=e('<p><em>图：采用常见的 105 × 68 米规格，不表示正式足球场只有这一种尺寸。大框是罚球区，俗称“大禁区”；小框是球门区，俗称“小禁区”。罚球区向场内延伸 16.5 米，球门区延伸 5.5 米；两种尺寸都是规则规定的区域深度，不随示例场地长宽同比缩放。省略角球弧等细节。</em></p><p><strong>罚球区不是“任何犯规都罚点球”的区域。</strong> 它影响守门员用手范围以及守方直接任意球犯规的处罚；球门区另有球门球、任意球等位置上的程序规定。罚球区外的圆弧用于罚球点球时的距离要求，不是罚球区的一部分。</p><h2 id="二、时间、进球与胜负" tabindex="-1">二、时间、进球与胜负 <a class="header-anchor" href="#二、时间、进球与胜负" aria-label="Permalink to &quot;二、时间、进球与胜负 {#二、时间、进球与胜负}&quot;">​</a></h2><p>标准比赛分上下半场，各 45 分钟，中场休息不超过 15 分钟。裁判为换人、伤病、拖延、庆祝进球、VAR 检查等损失的时间补时。第四官员显示的是<strong>最少补时时间</strong>，裁判可以增加，不能因显示了数字就提前结束。</p><p>球的整体越过两门柱之间、横梁下方的球门线，而且进球队没有先犯规，才算进球。终场进球多者获胜；相同则为平局，是否允许平局取决于赛事阶段。</p><p>需要分出胜负时，规程可以安排两节各不超过 15 分钟的加时，以及点球决胜。点球决胜与比赛中的罚球点球不同：通常双方先各踢 5 次，提前无法追平就结束；仍相同则按相同轮次逐轮比较，不是先罚进的一方立即获胜。点球决胜没有补射。</p><h2 id="三、开赛和恢复比赛" tabindex="-1">三、开赛和恢复比赛 <a class="header-anchor" href="#三、开赛和恢复比赛" aria-label="Permalink to &quot;三、开赛和恢复比赛 {#三、开赛和恢复比赛}&quot;">​</a></h2><p>开赛前掷币决定选择开球或进攻方向。开球时，除开球者外，所有队员在本方半场；对手距球至少 9.15 米。球被踢且明显移动后进入比赛，可以向任意方向开出。进球后由失球方开球。</p><table tabindex="0"><thead><tr><th>情形</th><th>恢复方式</th><th>容易混淆的地方</th></tr></thead><tbody><tr><td>球整体越过边线</td><td>最后触球队的对方掷界外球</td><td>面向场内，双手从头后经头上掷出，双脚各有一部分在边线上或线外地面</td></tr><tr><td>攻方最后触球后出底线且未进球</td><td>守方球门球</td><td>球踢出并明显移动即进入比赛，无须先离开罚球区</td></tr><tr><td>守方最后触球后出底线且未进球</td><td>攻方角球</td><td>可直接射入对方球门</td></tr><tr><td>直接任意球犯规</td><td>对方直接任意球</td><td>可以直接射门得分</td></tr><tr><td>间接任意球犯规</td><td>对方间接任意球</td><td>裁判举臂示意，进球前必须再碰到另一名队员</td></tr><tr><td>守方在本方罚球区内犯直接任意球犯规</td><td>罚球点球</td><td>并非罚球区内的所有犯规都判点球</td></tr></tbody></table><p>界外球不能直接得分；直接掷入对方球门判球门球，直接掷入本方球门判角球。恢复比赛的执行者通常不能在其他队员触球前再次触球，否则可能判间接任意球；手球等行为另按对应规则处理。</p><p>2026/27 规则进一步处理拖延：裁判认定掷界外球或球门球被拖延后，可以鸣哨并举手进行 <strong>5 秒倒数</strong>。界外球到时未进入比赛，改由对方掷；球门球到时未进入比赛，改判对方角球。这不等于每次球出界就自动开始 5 秒计时。</p><h2 id="四、越位-先看位置-再看是否参与" tabindex="-1">四、越位：先看位置，再看是否参与 <a class="header-anchor" href="#四、越位-先看位置-再看是否参与" aria-label="Permalink to &quot;四、越位：先看位置，再看是否参与 {#四、越位-先看位置-再看是否参与}&quot;">​</a></h2><h3 id="_1-越位位置的三个条件" tabindex="-1">1. 越位位置的三个条件 <a class="header-anchor" href="#_1-越位位置的三个条件" aria-label="Permalink to &quot;1. 越位位置的三个条件 {#_1-越位位置的三个条件}&quot;">​</a></h3><p>在队友踢球或触球的判定瞬间，头、躯干或脚的可判定部位同时满足：</p><ol><li>位于对方半场，中线不算对方半场。</li><li>比球更接近对方球门线。</li><li>比倒数第二名对方队员更接近对方球门线。</li></ol><p>手和手臂不参与比较，守门员也不例外。与倒数第二名对手平行不算越位位置。“倒数第二名对手”不一定是后卫，守门员也可能跑到前面。</p><p>一般取队友触球的第一个接触点；守门员手抛球则取球离手的最后接触点。判定时机是队友出球时，而不是接球队员拿到球时。</p><h3 id="_2-有位置-不一定有犯规" tabindex="-1">2. 有位置，不一定有犯规 <a class="header-anchor" href="#_2-有位置-不一定有犯规" aria-label="Permalink to &quot;2. 有位置，不一定有犯规 {#_2-有位置-不一定有犯规}&quot;">​</a></h3><p>处于越位位置的队员，只有随后参与实际比赛才会受罚，包括接触队友传来的球、遮挡对手视线、争抢球、作出明显影响对手处理球的动作，或接到门柱、横梁、对手反弹及扑救后的球而获利。</p><p><strong>直接接到球门球、界外球、角球，不判越位</strong>。但队友再传一次就要重新判断。对手有控制条件的主动处理球，通常会改变越位判断；单纯折射、反弹和有意救球不等同于主动处理球，不能概括为“碰过后卫就不越位”。</p><p>例如：前锋出球瞬间落后于球，随后跑到所有后卫前面接球，不越位。另一名前锋虽然没有碰球，却站在越位位置挡住门将看射门的视线，仍可能越位。越位犯规通常在其实际参与比赛的位置判间接任意球。</p><h2 id="五、身体接触、手球与红黄牌" tabindex="-1">五、身体接触、手球与红黄牌 <a class="header-anchor" href="#五、身体接触、手球与红黄牌" aria-label="Permalink to &quot;五、身体接触、手球与红黄牌 {#五、身体接触、手球与红黄牌}&quot;">​</a></h2><p>抢球时踢、绊、推、拉、冲撞等行为是否犯规，要看动作及程度；先碰到球不意味着随后危险动作合法。</p><table tabindex="0"><thead><tr><th>程度</th><th>判罚原则</th></tr></thead><tbody><tr><td>草率、欠缺注意</td><td>判犯规，通常不因动作程度出牌</td></tr><tr><td>鲁莽、无视危险</td><td>判犯规并黄牌警告</td></tr><tr><td>使用过分力量、危及对手安全</td><td>判犯规并红牌罚令出场</td></tr></tbody></table><p>拉人、推人等直接任意球犯规发生在本方罚球区内，通常判点球；没有接触的危险动作等可能判间接任意球。裁判可以在被犯规方仍有明显进攻利益时运用有利条款，必要的纪律处分可随后补给。</p><p><strong>球碰手不等于必然手球</strong>。主要判断是否故意用手臂触球，或手臂位置使身体不自然扩大，而且不能由当时身体动作合理解释。进攻队员直接用手臂进球，或者本人意外手球后立即进球，即使不是故意，进球也不成立；不能把这一条泛化成队友任何无意触手都必须取消进球。</p><p>黄牌还可能用于拖延恢复比赛、抗议判罚等行为。同一场累计两张黄牌会被红牌罚下。严重犯规、暴力行为、某些破坏明显进球机会的行为可以直接红牌；点球与红牌不是必然同时出现，须结合动作是否在争抢球、是否故意手球等判断。开赛后被罚下的球员不能由替补补齐。</p><h2 id="六、守门员与换人的特殊规则" tabindex="-1">六、守门员与换人的特殊规则 <a class="header-anchor" href="#六、守门员与换人的特殊规则" aria-label="Permalink to &quot;六、守门员与换人的特殊规则 {#六、守门员与换人的特殊规则}&quot;">​</a></h2><p>守门员只能在本方罚球区内依规则用手控球，在区外手球的判定与其他队员相同。队友故意用脚踢给门将，或队友直接掷界外球给门将，门将通常不能再用手接，否则判间接任意球。门将正常用脚处理球仍被允许。</p><p>门将在本方罚球区用手臂控制球超过 <strong>8 秒</strong>，判对方角球，角球在最接近门将受罚位置的一侧开出。裁判确定控制开始时刻，并举手倒数最后 5 秒。拍球、抛起再接住仍属于控制球，不会重置计时。不要继续套用旧版“6 秒后判间接任意球”的说法。</p><p>2026/27 的换人程序要求，被换下者通常在换人牌显示或裁判示意后 <strong>10 秒内</strong>离场，安全或伤情等例外除外。超时仍须离场，替补要等恢复比赛满 1 分钟后的首次停顿，经裁判允许才能进入；不是超时自动取消换人。业余比赛应由裁判事先说明执行安排。</p>',31))])}const m=r(i,[["render",p]]);export{_ as __pageData,m as default};
